    fontSize: 24,
    fontWeight: 'bold',
    color: '#ea580c', // orange-600
    marginBottom: 16,
    marginTop: 8,
  },
  itemsRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    justifyContent: 'center',
    gap: 24,
  },
  itemButton: {
    alignItems: 'center',
    backgroundColor: '#fef3c7', // yellow-100
    padding: 16,
    borderRadius: 16,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.15,
    shadowRadius: 4,
    elevation: 3,
    width: '45%',
    margin: 8,
