                </Text>
              </TouchableOpacity>
            </View>

            <Text style={styles.scriptureText}>{sampleText.repeat(10)}</Text>
          </ScrollView>

          {/* Floating Control Panel */}
          {showFloatingControls && (
            <View style={styles.floatingControlRow}>
              <View style={styles.switchRow}>
