import React from 'react';
import { View, TouchableOpacity, Text, StyleSheet } from 'react-native';
import { FontAwesome5, Ionicons, MaterialCommunityIcons } from '@expo/vector-icons';
import { useRouter, usePathname } from 'expo-router';

const BottomNavigation = () => {
  const router = useRouter();
  const pathname = usePathname();

  const tabs = [
    {
      name: 'Home',
      icon: 'home',
      iconType: 'FontAwesome5',
      route: '/screens/HomeScreen',
    },
    {
      name: 'Audio',
      icon: 'headset',
      iconType: 'Ionicons',
      route: '/screens/audio/audio-player',
    },
    {
      name: 'Scriptures',
      icon: 'book',
      iconType: 'FontAwesome5',
      route: '/screens/ScripturesScreen',
    },
    {
      name: 'Stories',
      icon: 'script-text-outline',
      iconType: 'MaterialCommunityIcons',
      route: '/screens/StoryScreen',
    },
    {
      name: 'Pooja',
      icon: 'candles',
      iconType: 'FontAwesome5',
      route: '/screens/PoojaRoomScreen',
    },
  ];

  const getIconComponent = (iconType: string, name: string, size: number, color: string) => {
    switch (iconType) {
      case 'FontAwesome5':
        return <FontAwesome5 name={name} size={size} color={color} />;
      case 'Ionicons':
        return <Ionicons name={name} size={size} color={color} />;
      case 'MaterialCommunityIcons':
        return <MaterialCommunityIcons name={name} size={size} color={color} />;
      default:
        return <FontAwesome5 name={name} size={size} color={color} />;
    }
  };

  const isActive = (route: string) => {
    return pathname === route || pathname.includes(route);
  };

  return (
    <View style={styles.container}>
      {tabs.map((tab, index) => (
        <TouchableOpacity
          key={index}
          style={styles.tab}
          onPress={() => router.push(tab.route)}
          activeOpacity={0.7}
        >
          {getIconComponent(
            tab.iconType,
            tab.icon,
            20,
            isActive(tab.route) ? '#f59e42' : '#fde68a'
          )}
          <Text
            style={[
              styles.tabText,
              { color: isActive(tab.route) ? '#f59e42' : '#fde68a' }
            ]}
          >
            {tab.name}
          </Text>
        </TouchableOpacity>
      ))}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    backgroundColor: 'rgba(124, 45, 18, 0.95)',
    paddingVertical: 10,
    paddingHorizontal: 5,
    borderTopWidth: 1,
    borderTopColor: 'rgba(245, 158, 66, 0.3)',
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    elevation: 8,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
  },
  tab: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: 5,
  },
  tabText: {
    fontSize: 10,
    marginTop: 4,
    fontWeight: '500',
  },
});

export default BottomNavigation;

